<!doctype html>
<html>

<head>
    <meta charset="utf-8">

    <style>
        @import url('http://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap');

        body {
            font-family: 'Roboto', sans-serif;
        }

        .f-left {
            float: left;
        }

        .f-right {
            float: right;
        }

        .t-right {
            text-align: right;
        }

        .t-center {
            text-align: center;
        }

        .t-left {
            text-align: left;
        }

        .logo-h {
            width: 300px;
            margin: 0px auto 30px;
        }
		.report-header-left {text-align: center;}
		.report-header-right {
    text-align: center;
}

.report-header-right h4 {
    font-size: 45px;
    margin-bottom: 10px;
}

.report-header-right p {
    font-size: 17px;
}

        .border {
            border: 1px solid #000;
            border-radius: 10px;
        }

        .full-width {
            padding: 15px;
            overflow: hidden;
        }

        .report p strong {
            font-size: 17px;
        }

        .report p {
            color: #000;
            margin: 0px;
            padding-top: 8px;
            font-size: 18px;
        }

        .report p a {
            color: #000;
        }

        .head-block {
            overflow: hidden;
            margin-bottom: 15px;
        }

        .full-width h4 {
            margin: 0px;
            color: #000;
            font-size: 20px;
        }

        .border-bottom {
            border-bottom: 1px solid #0000006e;
            overflow: hidden;
            padding-top: 15px;
            margin-bottom: 15px;
        }

        .vehicle-information .information-d {
            padding-top: 5px;
        }

        .vehicle-information ul {
            margin-top: 0px;
            padding-left: 15px;
        }

        .vehicle-information ul li {
            width: 45%;
            float: left;
            color: #000;
            font-size: 16px;
            display: block;
            padding: 12px 0px;
            position: relative;
            padding-left: 25px;
        }

        img.icon-logo {
            width: 25px;
            position: absolute;
            left: -2px;
            top: 10px;
        }

        .information-detail h3 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 35px;
        }

        .information-detail h5 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 35px;
        }

        .information-detail h1 {
            font-size: 40px;
            font-weight: bold;
            color: #000;
            margin: 0px;
        }

        .information-detail h1 sub {
            font-size: 20px;
            font-weight: 300;
        }

        .w-full {
            width: 100%;
        }

        .bottom-text {
            width: 100%;
            overflow: hidden;
            line-height: 15px;
        }

        .vehicle-information {
            overflow: hidden;
        }
    </style>
</head>

<body style="width:800px;margin:50px auto;">
    <div class="report" style="border: 1px solid #000; margin:50px 0px 0px;padding: 25px 10px 0px; position:relative;top:20px;">
        <div class="head-block">
            <div class="report-header-left">
                <img src="data:image/png;base64,
" class="logo-h" />
            </div>
            <div class="report-header-right t-center">
                <h4 style="margin-top:0px;"> {{YEAR}} {{MAKE}} {{MODEL}}</h4>
                <p><span class="stock"> Stock #: {{STOCK}}</span></p>
            </div>
			
			<div class="report-header-left t-center" style="margin: 80px 0px 0px;">
                <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;"> SCAN ME!</p>
                {{QR}}
            </div>
        </div>
        <div class="full-width">    
            <div class="information-detail">
                <div class="report-header-left f-left t-center" style="width:100%;padding: 15px 10px 15px 10px;">
                   <h3 style="font-weight: 700;padding-top: 8px;"> <img src="data:image/png;base64,
" style="max-width: 62px;width: 100%;position: relative;top: 16px;"/> 	{{BPHONE}} </h3>
                    <p>{{BADDRESS}}, {{BCITY}}, {{BSTATE}} {{BCODE}}</p>
                    
                </div>
            </div>
        </div>
    </div>
</body>

</html>